g=9.81;sf=1.5;reach=1.0;marm=25;payload=3;tool=1.2;car=8
dead=sf*g*(marm+payload+tool+car);full=sf*g*((marm+payload+tool)*reach+car*.15)
process=math.sqrt(100**2+10**2+20**2)
b=.150;h=.050;t=.003;E=200e9;G=77e9;span=2.80
I=2*(b*h**3-(b-2*t)*(h-2*t)**3)/12;Am=(b-t)*(h-t);J=2*4*Am**2/(2*((b-t)+(h-t))/t)
calc=dict(gravity_m_s2=g,dynamic_factor=sf,arm_mass_range_kg=[15,25],tool_payload_kg=payload,EOAT_additional_kg=tool,carriage_kg=car,conservative_full_reach_m=reach,UR5e_catalogue_reach_m=.85,
  full_reach_mass_envelope_Nm=full,gravity_carriage_force_N=dead,process_envelope_source='inputs/mandoline_golden.py: F=100N plus 10N lateral and 20N vertical, not a new cutting force',process_vector_norm_N=process,gravity_plus_process_design_Nm=full+sf*process*reach,
  selected_service_force_N=900,selected_service_moment_each_axis_Nm=650,selected_mass_capacity_kg=60,capacity_status='design requirement, not certified completed assembly',
  guide=dict(model='HGH25HA',blocks=4,block_dimensions_width_height_length_m=[.048,.040,.1046],rail_pair_spacing_m=.34,block_pair_spacing_m=.24,C_N_per_block=42200,C0_N_per_block=69070,static_moment_each_block_Nm=[560,730,730],worst_combined_reaction_bound_N=900/4+650/(2*.34)+2*650/(2*.24),minimum_static_safety_factor=3),
  steel_beam=dict(section_y_z_t_m=[b,h,t],tubes_per_lane=2,combined_width_y_m=.30,E_Pa=E,G_Pa=G,I_m4=I,J_approx_m4=J,support_spacing_m=span,vertical_deflection_900N_mm=900*span**3/(48*E*I)*1000,twist_650Nm_between_rigid_supports_deg=650*span/(4*G*J)*180/math.pi,twist_TCP_error_at_1m_mm=650*span/(4*G*J)*1000,mass_each_structural_2p8m_kg=2*(b*h-(b-2*t)*(h-2*t))*7850*2.8,note='Two parallel closed tubes assumed to share force/moment equally through rigid end restraints and crosshead. Rail2.4m on2.8m end-supported structure. Frame/weld/fastener flexibility NOT certified; no intermediate bracket across moving carriage path.'),
  rail_brake=dict(model='Miki BXR-050-10LE candidate',motor_static_Nm=3.2,reduction=10,pinion_radius_m=.02,conservative_efficiency=.8,holding_force_N=3.2*10*.8/.02,engagement_s=.060,speed_limit_m_s=.2,kinetic_energy_60kg_J=.5*60*.2**2,delay_distance_mm=.2*.060*1000,controlled_stop_distance_mm=.2**2/(2*1)*1000,reserved_stop_distance_mm=50,note='Needs actual shaft fit, brake status sensing, rotor/drive inertia and stopping-work allocation. Gearbox/friction not credited as a brake.'),
  joint_torque_policy='No transport screen grants continuous joint torque eligibility. Do NOT treat R01 UR5e/FR3 maximum or xArm motor-times-ratio limits as verified output continuous ratings.')
beam_mass=calc['steel_beam']['mass_each_structural_2p8m_kg']
calc['mount_load_bound']=dict(two_lane_wall_moment_Nm=2*650+sum(900*(.60-(-.06-.52*i))+beam_mass*g*(.60-(.165-.52*i)) for i in range(2)),three_lane_wall_moment_Nm=3*650+sum(900*(.60-(-.06-.52*i))+beam_mass*g*(.60-(.165-.52*i)) for i in range(3)),three_lane_structural_tube_mass_kg=3*beam_mass,note='Conservative simultaneous moment + force-standoff + beam gravity bound; excludes frame weight. Not an anchor allowable-load claim. 40mm portal members are clearance placeholders, not sized structural steel. Verified RC engineered anchorage or independently floor-anchored structural frame mandatory.')
write('sizing.json',calc)
