def rails(n,pitch=.52):
    return [dict(id=f'rail_{i+1}',axis=[1,0,0],physical_x_m=[-1.50,.90],carriage_center_travel_x_m=[-1.20,.70],arm_mount_y_m=-.06-pitch*i,arm_mount_z_m=1.230,
       beam_center_y_m=.165-pitch*i,beam_center_z_m=1.270,beam_size_m=[2.8,.30,.05],structural_x_m=[-1.78,1.02],guide_z_center_m=1.276,guide_outer_z_m=[1.252,1.300],guide_pair_spacing_m=.34,
       chain=dict(fixed_feed_x_m=-.30,swept_x_m=[-1.50,.90],swept_y_m=[.040-pitch*i,.285-pitch*i],swept_z_m=[1.297,1.322],bend_radius_m=.11,arrangement='horizontal bend plane ABOVE closed beam and BELOW arch crosshead; separate guarded trough per arm; no slot cut in torsion tube',cable='OEM Hiflex 6m arm lead plus rail encoder/control, OEM bend radius must be confirmed')) for i in range(n)]
def variant(id,n,pitch=.52,zslide=False):
    return dict(id=id,recommended=n<=3,rail_count=n,carriage_count=n,rail_assignment=list(range(1,n+1)),rails=rails(n,pitch),switches=[],transfer_shuttles=[],same_lane_overtaking=False,different_lane_passing=True,
      minimum_carriage_projection_gap_m=pitch-.495,minimum_folded_arm_projection_gap_m=pitch-fold['extent_m'][1],folded_aisle_remaining_at_arm_m=1.2+(-.06-pitch*(n-1)+fold['local_aabb_min_m'][1]),
      vertical_slide=dict(enabled=zslide,travel_m=[-.18,0] if zslide else [0,0],arm_mount_z_m=[1.050,1.230] if zslide else [1.230,1.230],passing_requires_slide_at_m=0,total_transport_mass_allowance_kg=16 if zslide else 8,brake='spring-applied motor brake plus direct rod brake for Z; no screw-self-lock credit' if zslide else None),
      note='One arm per lane. Three full-arm lanes overhang the opposite counter and cannot share the aisle with a person; third-arm task reach is NOT established. Four lanes cannot be installed in this representative galley. A three-rail/four-carriage cheaper variant cannot reorder the shared-lane pair.')
options=[]
rows=[]
def option(id,name,family,base,per,railprice=0,rank=None,eligibility='',power='',accuracy=None,sources=(),low=.65,high=1.6):
    budgets={str(n):int(base+per*n+railprice*n) for n in (2,3,4)}
    a=dict(id=id,name=name,family=family,rank=rank,eligibility=eligibility,cost_cny=budgets,cost_basis='engineering planning estimate; numeric matched supplier quote unavailable',power_data=power,stop_accuracy_mm=accuracy,source_ids=list(sources))
    options.append(a)
    for n,c in budgets.items():rows.append(dict(option_id=id,carriages=n,run_m=2.4,rail_count=n if id.startswith('passing') else (2 if family=='switch_transfer' else ''),cost_low_cny=round(c*low/1000)*1000,cost_base_cny=c,cost_high_cny=round(c*high/1000)*1000,includes='transport guides drive spring_brakes power_data guards safety integration_allowance',excludes='cobots EOAT appliances wall_rebuild certified_cell_NRE',basis='planning_estimate_not_quote',source_ids=';'.join(sources),price_date='2026-10-07',notes=eligibility))
