option('passing_xz_cable','Independent rails with 180mm Z slide per carriage','simple_xz',24000,26000,9000,2,'Second choice only when IK benefits justify Z; upper Z position required to pass.','same chains plus short Z service loop; controllers fixed',.10,['S01','S19','S20','S24'])
