option('acopostrak','B&R ACOPOStrak diverter layout','switch_transfer',130000,25000,rank=8,eligibility='Native 1-2kg movers fail cobot mass and moment; cost refers to lightweight cell, not compliant heavy-arm transport.',power='separate arm busbar/inductive; stator supply does not power payload',accuracy=.15,sources=['S04'])
