option('xplanar','Beckhoff XPlanar coupled heavy groups','planar',340000,130000,rank=11,eligibility='4.5kg individual movers fail. At least14 movers for60kg mass before moment/vertical derating. A2x7 group may fit alone (~1.68x0.48m), but two cannot pass in a2.4x0.5m backsplash. Not a compliant system.',power='arm requires separate kW inductive supply; native product motion power is not payload power',accuracy=None,sources=['S09','S10'],high=2.0)
